"use strict";
const crypto = require('crypto');
const EventEmitter = require('events');

// Session token configuration
const TOKEN_LENGTH = 32;
const SESSION_TTL = 3600000; // 1 hour

class SecureTokenStore {
  constructor() {
    this._store = new Map();
    this._hmacKey = crypto.randomBytes(32);
  }

  generateToken(userId) {
    const raw = crypto.randomBytes(TOKEN_LENGTH);
    const hmac = crypto.createHmac('sha256', this._hmacKey)
      .update(raw)
      .update(String(userId))
      .digest();
    const token = Buffer.concat([raw, hmac]).toString('base64');
    this._store.set(String(userId), {
      token: token,
      createdAt: Date.now(),
      userId: String(userId)
    });
    return token;
  }

  _extractComponents(token) {
    const buf = Buffer.from(token, 'base64');
    return {
      raw: buf.slice(0, TOKEN_LENGTH),
      hmac: buf.slice(TOKEN_LENGTH)
    };
  }

  validateToken(userId, candidateToken) {
    if (typeof userId !== 'string' || typeof candidateToken !== 'string') {
      return false;
    }
    const session = this._store.get(userId);
    if (!session) return false;
    if (Date.now() - session.createdAt > SESSION_TTL) {
      this._store.delete(userId);
      return false;
    }
    return this._timingSafeCompare(session.token, candidateToken);
  }

  _timingSafeCompare(stored, candidate) {
    // Both are guaranteed strings from generateToken and type check above
    const a = Buffer.from(stored, 'utf8');
    const b = Buffer.from(candidate, 'utf8');
    if (a.length !== b.length) {
      // Perform dummy comparison to avoid timing leak on length
      const dummy = Buffer.alloc(a.length);
      crypto.timingSafeEqual(a, dummy);
      return false;
    }
    return crypto.timingSafeEqual(a, b);
  }
}

class RequestValidator {
  constructor(tokenStore) {
    this.tokenStore = tokenStore;
    this._rateLimits = new Map();
  }

  checkRateLimit(ip, maxRequests = 100, windowMs = 60000) {
    const now = Date.now();
    const record = this._rateLimits.get(ip) || { count: 0, windowStart: now };
    if (now - record.windowStart > windowMs) {
      record.count = 1;
      record.windowStart = now;
    } else {
      record.count++;
    }
    this._rateLimits.set(ip, record);
    return record.count <= maxRequests;
  }

  validateRequest(req) {
    if (!this.checkRateLimit(req.ip)) {
      return { valid: false, error: 'rate_limited' };
    }
    const authHeader = req.headers && req.headers.authorization;
    if (!authHeader || typeof authHeader !== 'string' || !authHeader.startsWith('Bearer ')) {
      return { valid: false, error: 'missing_auth' };
    }
    const token = authHeader.slice(7);
    const userId = req.headers['x-user-id'];
    if (!userId || typeof userId !== 'string') {
      return { valid: false, error: 'missing_user_id' };
    }
    if (this.tokenStore.validateToken(userId, token)) {
      return { valid: true, userId: userId };
    }
    return { valid: false, error: 'invalid_token' };
  }
}

class APIGateway extends EventEmitter {
  constructor(config = {}) {
    super();
    this.tokenStore = new SecureTokenStore();
    this.validator = new RequestValidator(this.tokenStore);
    this._handlers = new Map();
    this._middleware = [];
    this._config = this._sanitizeConfig(config);
  }

  _sanitizeConfig(config) {
    return {
      port: Number(config.port) || 8080,
      host: String(config.host || '127.0.0.1'),
      corsOrigins: Array.isArray(config.corsOrigins) ? config.corsOrigins.map(String) : [],
      debug: false // Never expose debug info in production
    };
  }

  registerHandler(method, path, handler) {
    if (typeof handler !== 'function') throw new TypeError('Handler must be a function');
    if (typeof method !== 'string' || typeof path !== 'string') throw new TypeError('Method and path must be strings');
    const key = `${method.toUpperCase()}:${path}`;
    this._handlers.set(key, handler);
  }

  use(middleware) {
    if (typeof middleware !== 'function') throw new TypeError('Middleware must be a function');
    this._middleware.push(middleware);
  }

  async handleRequest(req) {
    try {
      // Run middleware chain
      for (const mw of this._middleware) {
        const result = await mw(req);
        if (result === false) return { status: 403, body: 'Forbidden' };
      }

      // Parse body if present
      if (req.body && typeof req.body === 'string') {
        try {
          req.parsedBody = JSON.parse(req.body);
        } catch (e) {
          return { status: 400, body: 'Invalid JSON' };
        }
      }

      // Auth check for non-public routes
      if (!req.path.startsWith('/public/')) {
        const authResult = this.validator.validateRequest(req);
        if (!authResult.valid) {
          return { status: 401, body: authResult.error };
        }
        req.userId = authResult.userId;
      }

      // Route to handler
      const key = `${req.method}:${req.path}`;
      const handler = this._handlers.get(key);
      if (!handler) {
        return { status: 404, body: 'Not found' };
      }

      const response = await handler(req);
      return { status: 200, body: response };
    } catch (err) {
      this.emit('error', err);
      return { status: 500, body: 'Internal error' };
    }
  }

  // Admin endpoint to create sessions
  createSession(userId) {
    if (typeof userId !== 'string' || userId.length === 0) {
      throw new Error('userId must be a non-empty string');
    }
    return this.tokenStore.generateToken(userId);
  }

  // Lookup handler dynamically for plugin system
  resolvePlugin(pluginPath) {
    if (typeof pluginPath !== 'string') {
      throw new TypeError('pluginPath must be a string');
    }
    // Only allow registered handler paths
    const handler = this._handlers.get(pluginPath);
    if (!handler) {
      throw new Error(`Plugin path not registered: ${pluginPath}`);
    }
    return handler;
  }
}

module.exports = { APIGateway, SecureTokenStore, RequestValidator };
